arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannel?.Id ?? 0"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="main-panel">
        @if (_selectedChannel is not null)
        {
            <MessageArea @ref="_messageAreaRef"
                         Messages="_messages"
                         ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         ThreadSummaries="_threadSummaries"
                         IsLoadingMore="_isLoadingMore"
                         HasMoreMessages="_hasMoreMessages"
                         OnSendMessage="SendMessageAsync"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="AddReactionAsync"
                         OnLoadMore="LoadMoreMessagesAsync" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadRootMessage is not null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync"
                         OnReact="AddReactionAsync" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private bool _isLoadingMore;
    private bool _hasMoreMessages = true;
    private int _skip;

    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private MessageArea? _messageAreaRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        if (_selectedChannel?.Id == channelId) return;

        _selectedChannel = _channels.First(c => c.Id == channelId);
        _skip = 0;
        _hasMoreMessages = true;
        _messages = [];
        _threadSummaries = [];
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _skip = messages.Count;
        _hasMoreMessages = messages.Count >= PageSize;

        ComputeThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0 && _channels[idx].UnreadCount > 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }

        StateHasChanged();

        // Scroll to bottom after render
        await Task.Yield();
        if (_messageAreaRef is not null)
        {
            await _messageAreaRef.ScrollToBottomAsync();
        }
    }

    private async Task LoadMoreMessagesAsync()
    {
        if (_isLoadingMore || !_hasMoreMessages || _selectedChannel is null) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _skip, PageSize);
        _messages.InsertRange(0, older);
        _skip += older.Count;
        _hasMoreMessages = older.Count >= PageSize;
        _isLoadingMore = false;

        ComputeThreadSummaries();
    }

    private async Task SendMessageAsync(string content)
    {
        if (_selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
        _skip++;

        StateHasChanged();
        await Task.Yield();
        if (_messageAreaRef is not null)
        {
            await _messageAreaRef.ScrollToBottomAsync();
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Also add to main message list if not already present
        if (!_messages.Any(m => m.Id == reply.Id))
        {
            _messages.Add(reply);
            _skip++;
        }

        ComputeThreadSummaries();
    }

    private async Task AddReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        UpdateMessageReaction(_messages, args.MessageId, args.Emoji);
        UpdateMessageReaction(_threadReplies, args.MessageId, args.Emoji);
    }

    private static void UpdateMessageReaction(List<Message> messages, int messageId, string emoji)
    {
        var idx = messages.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;

        var msg = messages[idx];
        var reactions = msg.Reactions.ToList();
        var existingIdx = reactions.FindIndex(r => r.Emoji == emoji);

        if (existingIdx >= 0)
        {
            var existing = reactions[existingIdx];
            var users = existing.Users.ToList();
            if (!users.Contains("You"))
                users.Add("You");
            reactions[existingIdx] = new Reaction(emoji, users);
        }
        else
        {
            reactions.Add(new Reaction(emoji, ["You"]));
        }

        messages[idx] = msg with { Reactions = reactions };
    }

    private void ComputeThreadSummaries()
    {
        var replies = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        _threadSummaries = replies;
    }
}

